-- Read-only diagnostic for the exact failing event IDs in the 2026-10-15 audit.
-- Execute inside a read-only transaction. Raw prior sums do NOT authorize
-- inventory: canonical baselines, original identity and all parents still need proof.
-- The current-receipt fallback columns are comparisons, never a provenance repair.
WITH rows AS (SELECT a.*,coalesce(a."GrowerLotId",r."GrowerLotId") normalized_grower,coalesce(a."FruitProfileId",r."FruitProfileId") normalized_profile,coalesce(a."CropYear",r."CropYear") normalized_year FROM "RoomInventoryAdjustments" a LEFT JOIN "Receipts" r ON r."Id"=a."ReceiptId")
SELECT coalesce(json_agg(z),'[]') FROM (SELECT a."Id",a."RoomId",a."LotNumber",a."ChangeAmount",a."ReceiptId",a."ReceiptInventoryOverrideId",a."InventoryIdentityCorrectionId",a."GrowerLotId",a.normalized_grower,
(SELECT coalesce(sum(b."ChangeAmount"),0) FROM rows b WHERE b."RoomId"=a."RoomId" AND b."WarehouseId"=a."WarehouseId" AND (b."CreatedAt",b."Id")<(a."CreatedAt",a."Id") AND b."CropYear" IS NOT DISTINCT FROM a."CropYear" AND b."GrowerLotId" IS NOT DISTINCT FROM a."GrowerLotId" AND b."FruitProfileId" IS NOT DISTINCT FROM a."FruitProfileId" AND upper(trim(b."LotNumber"))=upper(trim(a."LotNumber"))) raw_prior,
(SELECT coalesce(sum(b."ChangeAmount"),0) FROM rows b WHERE b."RoomId"=a."RoomId" AND b."WarehouseId"=a."WarehouseId" AND (b."CreatedAt",b."Id")<(a."CreatedAt",a."Id") AND b.normalized_year IS NOT DISTINCT FROM a.normalized_year AND b.normalized_grower IS NOT DISTINCT FROM a.normalized_grower AND b.normalized_profile IS NOT DISTINCT FROM a.normalized_profile AND upper(trim(b."LotNumber"))=upper(trim(a."LotNumber"))) normalized_prior,
(SELECT json_agg(json_build_object('id',b."Id",'growerLot',b."GrowerLotId",'profile',b."FruitProfileId",'quantity',b."ChangeAmount")) FROM rows b WHERE a."ReceiptInventoryOverrideId" IS NOT NULL AND b."ReceiptInventoryOverrideId"=a."ReceiptInventoryOverrideId") correction_siblings,
(SELECT json_build_object('id',v."Id",'complete',v."IsComplete",'action',v."ActionType",'before',v."BeforeReceiptSnapshotJson"::json,'after',v."AfterReceiptSnapshotJson"::json) FROM "ReceiptInventoryOverrides" v WHERE v."ReceiptId"=a."ReceiptId" ORDER BY v."CreatedAt",v."Id" LIMIT 1) original_revision,
(SELECT json_build_object('id',c."Id",'quantity',c."BinCount",'growerLot',c."GrowerLotId",'profile',c."FruitProfileId") FROM "Receipts" c WHERE c."Id"=a."ReceiptId") current_receipt
FROM rows a WHERE a."Id" IN (143,151,277,404,463,478,521,543,548,566,673,681,687,689,711,737,747,815,868,870,882,952,981,987,1053,1084,1094,1120,1187,1254,1282,1284,1306,1329,1331,1333,1506,1633,1648,1710,1884,1908,2081,2083,2214,2216,2221,2225,2296,2671,2726,2728,2730) ORDER BY a."Id") z;
